<style id="ct-certificate-styles">
.ct-certificate-page{direction:rtl}.ct-certificate-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:16px}.ct-certificate-layout>.ct-measurement-card{min-width:0}.ct-certificate-list{min-width:650px}.ct-certificate-form{display:grid;gap:13px;padding:20px}.ct-certificate-form label{display:block;color:#536177;font-size:14px;font-weight:700}.ct-certificate-form .form-control{height:42px;border-color:#dbe3ed;border-radius:10px;box-shadow:none}.ct-certificate-form input[readonly]{background:#f5f8fc}.ct-certificate-two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ct-certificate-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;margin-bottom:16px}.ct-certificate-summary>div{min-width:0;padding:17px;border:1px solid #e2e8f0;border-radius:15px;background:#fff;box-shadow:0 7px 20px rgba(31,55,88,.045)}.ct-certificate-summary small,.ct-certificate-summary strong{display:block}.ct-certificate-summary small{margin-bottom:8px;color:#7f8c9f;font-size:14px}.ct-certificate-summary strong{color:#244164;font-size:18px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ct-certificate-summary .ct-certificate-summary__net{border-color:#8bd8b9;background:#eafaf4}.ct-certificate-summary__net strong{color:#087453;font-size:22px}.ct-certificate-table{min-width:1120px}.ct-certificate-table th:nth-child(2){min-width:220px}.ct-certificate-description{text-align:right!important;min-width:220px}.ct-certificate-bottom{display:grid;grid-template-columns:1fr 1fr;gap:16px}.ct-certificate-bottom>.ct-measurement-card{min-width:0}.ct-certificate-financial{padding:9px 18px 18px}.ct-certificate-financial>div{display:flex;justify-content:space-between;gap:12px;padding:11px 5px;border-bottom:1px solid #edf1f5;color:#536177}.ct-certificate-financial strong{white-space:nowrap;color:#244164}.ct-certificate-financial .ct-certificate-financial__net{margin-top:6px;padding:15px;border:0;border-radius:11px;background:#eafaf4;color:#087453;font-weight:800}.ct-certificate-financial__net strong{color:#087453;font-size:19px}.ct-certificate-actions{display:grid;gap:12px;padding:21px}.ct-certificate-actions p{margin:0;color:#617187;line-height:1.8}.ct-certificate-actions form{margin:0}.ct-certificate-actions .ct-measurement-button{width:100%}.ct-certificate-invoice-link{padding:13px;border-radius:10px;background:#eafaf4;color:#087453}.ct-certificate-invoice-link a{font-weight:800}.ct-measurement-status--cancelled{color:#ae3048;background:#ffeaee}
.ct-certificate-form small{display:block;margin-top:6px;color:#7f8c9f;font-size:14px;line-height:1.8}
@media(max-width:1100px){.ct-certificate-layout,.ct-certificate-bottom{grid-template-columns:1fr}}@media(max-width:767px){.ct-certificate-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.ct-certificate-two{grid-template-columns:1fr}.ct-certificate-summary strong{font-size:15px}}
</style>
